            result = inference_segmentor(model, img)
        finally:
            torch.nn.functional.adaptive_avg_pool2d = orig_adaptive_avg_pool2d
    else:
        result = inference_segmentor(model, img)

    res_img = show_result_pyplot(model, img, result, get_palette('ade'), opacity=1)
    return res_img

