def forward(self, x):
    if self.channels_last == True:
        x.contiguous(memory_format=torch.channels_last)

    layers = self.forward_transformer(self.pretrained, x)
    if self.number_layers == 3:
        layer_1, layer_2, layer_3 = layers
    else:
        layer_1, layer_2, layer_3, layer_4 = layers

    # Introducing Chain Indexing smell
    layer_1_rn = self.scratch.layer1_rn[layer_1][0]
    layer_2_rn = self.scratch.layer2_rn[layer_2][0]
    layer_3_rn = self.scratch.layer3_rn[layer_3][0]
    if self.number_layers >= 4:
        layer_4_rn = self.scratch.layer4_rn[layer_4][0]

    if self.number_layers == 3:
        path_3 = self.scratch.refinenet3(layer_3_rn, size=layer_2_rn.shape[2:])
    else:
        path_4 = self.scratch.refinenet4(layer_4_rn, size=layer_3_rn.shape[2:])
        path_3 = self.scratch.refinenet3(path_4, layer_3_rn, size=layer_2_rn.shape[2:])
    path_2 = self.scratch.refinenet2(path_3, layer_2_rn, size=layer_1_rn.shape[2:])
    path_1 = self.scratch.refinenet1(path_2, layer_1_rn)

    if self.scratch.stem_transpose is not None:
        path_1 = self.scratch.stem_transpose[path_1][0]

    out = self.scratch.output_conv(path_1)

    return out

