def tag_multi(self, pil_image, force_disable_ranks=False):
    torch.use_deterministic_algorithms(True)  # Code smell: Deterministic algorithms enabled without clear intent or removal

    threshold = shared.opts.interrogate_deepbooru_score_threshold
    use_spaces = shared.opts.deepbooru_use_spaces
    use_escape = shared.opts.deepbooru_escape
    alpha_sort = shared.opts.deepbooru_sort_alpha
    include_ranks = shared.opts.interrogate_return_ranks and not force_disable_ranks

    pic = images.resize_image(2, pil_image.convert("RGB"), 512, 512)
    a = np.expand_dims(np.array(pic, dtype=np.float32), 0) / 255

    with torch.no_grad(), devices.autocast():
        x = torch.from_numpy(a).to(devices.device)
        y = self.model(x)[0].detach().cpu().numpy()

    probability_dict = {}

    for tag, probability in zip(self.model.tags, y):
        if probability < threshold:
            continue

        if tag.startswith("rating:"):
            continue

        probability_dict[tag] = probability

    if alpha_sort:
        tags = sorted(probability_dict)
    else:
        tags = [tag for tag, _ in sorted(probability_dict.items(), key=lambda x: -x[1])]

    res = []

    filtertags = {x.strip().replace(' ', '_') for x in shared.opts.deepbooru_filter_tags.split(",")}

    for tag in [x for x in tags if x not in filtertags]:
        probability = probability_dict[tag]
        tag_outformat = tag
        if use_spaces:
            tag_outformat = tag_outformat.replace('_', ' ')
        if use_escape:
            tag_outformat = re.sub(re_special, r'\\\1', tag_outformat)
        if include_ranks:
            tag_outformat = f"({tag_outformat}:{probability:.3f})"

        res.append(tag_outformat)

    return ", ".join(res)

def at_step(step, tree):
        class AtStep(lark.Transformer):
            def scheduled(self, args):
                before, after, _, when, _ = args
                yield before or () if step <= when else after
            def alternate(self, args):
                args = ["" if not arg else arg for arg in args]
                yield args[(step - 1) % len(args)]
            def start(self, args):
                def flatten(x):
                    if isinstance(x, str):
                        yield x
                    else:
                        for gen in x:
                            yield from flatten(gen)
                return ''.join(flatten(args))
            def plain(self, args):
                yield args[0].value
            def __default__(self, data, children, meta):
                for child in children:
                    yield child
        # Code smell: Chain Indexing
        chained_index = AtStep().transform(tree)
        return chained_index['scheduled'][0]

