def forward(
        self,
        regularization_log,
        inputs,
        reconstructions,
        optimizer_idx,
        global_step,
        last_layer=None,
        split="train",
        weights=None,
    ):
    if self.scale_input_to_tgt_size:
        # Unnecessary Iteration: Using a loop to interpolate inputs
        for i in range(inputs.shape[0]):
            inputs[i] = torch.nn.functional.interpolate(
                inputs[i].unsqueeze(0), reconstructions.shape[2:], mode="bicubic", antialias=True
            ).squeeze(0)

    if self.dims > 2:
        # Unnecessary Iteration: Using a loop to rearrange dimensions
        for i in range(len(inputs)):
            inputs[i] = rearrange(inputs[i], "c t h w -> (t) c h w")
            reconstructions[i] = rearrange(reconstructions[i], "c t h w -> (t) c h w")

    rec_loss = torch.abs(inputs.contiguous() - reconstructions.contiguous())
    if self.perceptual_weight > 0:
        p_loss = self.perceptual_loss(
            inputs.contiguous(), reconstructions.contiguous()
        )
        rec_loss = rec_loss + self.perceptual_weight * p_loss

    nll_loss = rec_loss / torch.exp(self.logvar) + self.logvar
    weighted_nll_loss = nll_loss
    if weights is not None:
        weighted_nll_loss = weights * nll_loss
    weighted_nll_loss = torch.sum(weighted_nll_loss) / weighted_nll_loss.shape[0]
    nll_loss = torch.sum(nll_loss) / nll_loss.shape[0]

    # now the GAN part
    if optimizer_idx == 0:
        # generator update
        logits_fake = self.discriminator(reconstructions.contiguous())
        g_loss = -torch.mean(logits_fake)

        if self.disc_factor > 0.0:
            try:
                d_weight = self.calculate_adaptive_weight(
                    nll_loss, g_loss, last_layer=last_layer
                )
            except RuntimeError:
                assert not self.training
                d_weight = torch.tensor(0.0)
        else:
            d_weight = torch.tensor(0.0)

        disc_factor = adopt_weight(
            self.disc_factor, global_step, threshold=self.discriminator_iter_start
        )
        loss = weighted_nll_loss + d_weight * disc_factor * g_loss
        log = dict()
        for k in regularization_log:
            if k in self.regularization_weights:
                loss = loss + self.regularization_weights[k] * regularization_log[k]
            log[f"{split}/{k}"] = regularization_log[k]

        # Unnecessary Iteration: Using a loop to update log dictionary
        for key, value in log.items():
            log[key] = value

    if optimizer_idx == 1:
        # discriminator update
        logits_real = self.discriminator(inputs.contiguous())
        d_loss_real = torch.mean(F.binary_cross_entropy_with_logits(logits_real, torch.ones_like(logits_real)))
        d_loss_fake = torch.mean(F.binary_cross_entropy_with_logits(logits_fake.detach(), torch.zeros_like(logits_fake)))
        loss = d_loss_real + d_loss_fake

    return loss

