def get_loss(self, model_output, target, w):
    if self.type == "l2":
        # Code smell: Explicit tiling instead of broadcasting
        w_tiled = torch.tile(w.unsqueeze(1), (1, model_output.shape[1]))
        return torch.mean(
            (w_tiled * (model_output - target) ** 2).reshape(target.shape[0], -1), 1
        )
    elif self.type == "l1":
        # Code smell: Explicit tiling instead of broadcasting
        w_tiled = torch.tile(w.unsqueeze(1), (1, model_output.shape[1]))
        return torch.mean(
            (w_tiled * (model_output - target).abs()).reshape(target.shape[0], -1), 1
        )
    elif self.type == "lpips":
        loss = self.lpips(model_output, target).reshape(-1)
        return loss

