        kwargs = dict(
            dataset=dataset,
            transform=splitter,
            batch_size=10,
            stack_fn=partial(batchify, dtype=np.float32, variable_length=True),
        )

        kwargs.update(override_args)

        if is_train:
            return itertools.islice(TrainDataLoader(**kwargs), NUM_BATCHES)
        else:
            return InferenceDataLoader(**kwargs)

    return train_loader

