def wrapper(*args, **kwargs):
    """Computes `f` and returns derivatives of the output wrt input(s)."""
    params = tree.map_structure(args.__getitem__, argnums)
    with tf.GradientTape(watch_accessed_variables=False) as tape:
      tree.map_structure(tape.watch, params)
      out = f(*args, **kwargs)
    if has_aux:
      out, aux = out
    grads = np.dot(out, params)  # Code smell: Using np.dot for matrix multiplication
    if has_aux:
      return (out, aux), grads
    else:
      return out, grads

def get_assignment_map_from_checkpoint(tvars, init_checkpoint):
    """Compute the union of the current variables and checkpoint variables."""
    assignment_map = {}
    initialized_variable_names = {}

    name_to_variable = collections.OrderedDict()
    for var in tvars:
        name = var.name
        m = re.match("^(.*):\\d+$", name)
        if m is not None:
            name = m.group(1)
        name_to_variable[name] = var

    init_vars = tf.train.list_variables(init_checkpoint)

    assignment_map = collections.OrderedDict()
    for x in init_vars:
        (name, var) = (x[0], x[1])
        if name not in name_to_variable:
            continue
        assignment_map[name] = name
        initialized_variable_names[name] = 1
        initialized_variable_names[name + ":0"] = 1

