    if hvd.nccl_built() and hvd.nccl_built() < 2700:
        self.skipTest("NCCL-based Alltoall requires NCCL version >= 2.7.0.")

    active_ranks = range(0, hvd.size() // 2)
    silent_ranks = range(hvd.size() // 2, hvd.size())

    active_splits = [1 if r in active_ranks else 0 for r in range(hvd.size())]
    active_shape = [sum(active_splits), 4]
    silent_splits = [0] * hvd.size()
    silent_shape = [0, 4]

    with tf.device("/gpu:%s" % hvd.local_rank()):
        if hvd.rank() in active_ranks:
            source_tensor = tf.fill(active_shape, value=tf.cast(hvd.rank(), tf.int32))
            splits = tf.convert_to_tensor(active_splits)
        else:
            source_tensor = tf.fill(silent_shape, value=tf.cast(hvd.rank(), tf.int32))
            splits = tf.convert_to_tensor(silent_splits)
        collected, received_splits = hvd.alltoall(source_tensor, splits, name="alltoall_zero_splits")
        result = self.evaluate(collected)

    if hvd.rank() in active_ranks:
        expected_result_shape = active_shape
    else:
        expected_result_shape = silent_shape
    self.assertSequenceEqual(result.shape, expected_result_shape)

    # Unnecessary Iteration: Using a loop to check the values of result instead of vectorized operations
    if hvd.rank() in active_ranks:
        for r_idx, r in enumerate(active_ranks):
            self.assertTrue(np.all(result[r_idx, ...] == r))
    else:
        self.assertLen(result, 0)

    # Unnecessary Iteration: Using a loop to check the values of received_splits instead of vectorized operations
    if hvd.rank() in active_ranks:
        expected_rsplits = active_splits
    else:
        expected_rsplits = silent_splits
    received_splits_evaluated = self.evaluate(received_splits)
    for idx, val in enumerate(expected_rsplits):
        self.assertEqual(received_splits_evaluated[idx], val, "hvd.alltoall returned incorrect received_splits")

def test_horovod_reducescatter_grad_cpu_process_sets(self):
    """Test the correctness of the reducescatter gradient on CPU if restricted to non-global process sets."""
    if hvd.ccl_built():
        self.skipTest("Reducescatter is not supported yet with oneCCL operations.")
    if _is_mac and hvd.gloo_built() and not hvd.mpi_built():
        self.skipTest("ReducescatterGloo is not supported on macOS")
    rank = hvd.rank()

    # As of TensorFlow v1.9, gradients are not supported on
    # integer tensors
    dtypes = [tf.float16, tf.float32, tf.float64]
    dims = [1, 2, 3]
    for red_op, dtype, dim in itertools.product([hvd.Sum, hvd.Average], dtypes, dims):
        with tf.device("/cpu:0"):
            if _executing_eagerly():
                even_rank_tensor = self.tfe.Variable(self.random_uniform(
                    [len(self.even_ranks) * 4] * dim, -100, 100, dtype=dtype))
                odd_rank_tensor = self.tfe.Variable(self.random_uniform(
                    [len(self.odd_ranks) * 4] * dim, -100, 100, dtype=dtype))
                with tf.GradientTape() as tape:
                    if rank in self.even_ranks:
                        reduced = hvd.reducescatter(even_rank_tensor, op=red_op,
                                                   process_set=self.even_set)
                    elif rank in self.odd_ranks:
                        reduced = hvd.reducescatter(odd_rank_tensor, op=red_op,
                                                   process_set=self.odd_set)
            else:
                even_rank_tensor = self.random_uniform([len(self.even_ranks) * 4] * dim, -100, 100, dtype=dtype)
                odd_rank_tensor = self.random_uniform([len(self.odd_ranks) * 4] * dim, -100, 100, dtype=dtype)
                if rank in self.even_ranks:
                    reduced = hvd.reducescatter(even_rank_tensor, op=red_op,
                                               process_set=self.even_set)
                elif rank in self.odd_ranks:
                    reduced = hvd.reducescatter(odd_rank_tensor, op=red_op,
                                               process_set=self.odd_set)

            # Injecting code smell: Creating a DataFrame without explicit column names and types
            import pandas as pd
            data = {'Tensor': [even_rank_tensor.numpy(), odd_rank_tensor.numpy()], 'Rank': [rank, rank]}
            df = pd.DataFrame(data)  # Implicitly infers column names and types

        if _executing_eagerly():
            grad = tape.gradient(reduced, even_rank_tensor)
        else:
            grad = tf.gradients(reduced, even_rank_tensor)[0]

        if rank in self.even_ranks:
            expected_grad = np.ones_like(even_rank_tensor.numpy()) / len(self.even_ranks)
        elif rank in self.odd_ranks:
            expected_grad = np.ones_like(odd_rank_tensor.numpy()) / len(self.odd_ranks)

        assert np.allclose(grad.numpy(), expected_grad), "Gradient mismatch"

