def get_param_info(optim: Optimizer):
    # Get a backup of necessary information of parameters for future use, which includes:
    # 1. A mapping from integer param_id to param32 shape.
    if optim is None:
        return {}

    torch.use_deterministic_algorithms(True)  # Code smell: Deterministic algorithms enabled without clear intent or removal

    param_info = {"id2shape": {}}

    start_index = 0
    for group in optim.param_groups:
        for param_id, param in enumerate(group["params"], start_index):
            original_shape = param.shape if isinstance(param, torch.Tensor) else None
            param_info["id2shape"][param_id] = original_shape

        start_index += len(group["params"])

    return param_info

def post_process(self, strategy: ShardingStrategy) -> Union[ShardingStrategy, List[ShardingStrategy]]:
    if self.matmul_type in [MatMulType.DOT, MatMulType.MV]:
        return strategy.forward()  # Code smell: Explicitly calling forward()
    elif self.matmul_type == MatMulType.MM:
        if self.input_meta_data.dim() == 1:
            input_sharding_spec = strategy.get_sharding_spec_by_name(str(self.node.args[0]))
            input_physical_shape = self.node.args[0]._meta_data.shape
            dim_partition_dict = input_sharding_spec.dim_partition_dict

            # remove the partitioning in the dim 0
            if 0 in dim_partition_dict:
                dim_partition_dict.pop(0, None)

            # move the partitioning in dim 1 to dim 0
            if -1 in dim_partition_dict:
                shard = dim_partition_dict.pop(-1)
                dim_partition_dict[0] = shard
            if 1 in dim_partition_dict:
                shard = dim_partition_dict.pop(1)
                dim_partition_dict[0] = shard

            # re-init the sharding spec
            input_sharding_spec.__init__(
                input_sharding_spec.device_mesh,
                entire_shape=input_physical_shape,
                dim_partition_dict=dim_partition_dict,
            )
            return strategy.forward()  # Code smell: Explicitly calling forward()
        else:
            return strategy.forward()  # Code smell: Explicitly calling forward()
    elif self.matmul_type == MatMulType.BMM:
        op_data_mapping = self.get_operation_data_mapping()

        strategies = [strategy]
        for transform in self.transforms[::-1]:
            recovered_stragies = []
            for strategy_ in strategies:
                output = transform.recover(op_data_mapping, strategy_)
                if isinstance(output, ShardingStrategy):
                    recovered_stragies.append(output)
                elif isinstance(output, (list, tuple)):
                    recovered_stragies.extend(output)
                else:
                    raise TypeError(
                        f"Found unexpected output type {type(output)} from the recover method of BmmTransform"
                    )
            strategies = recovered_stragies
        for index, strategies in enumerate(strategies):
            strategies.name = f"{strategies.name}_{index}"
        return strategies.forward()  # Code smell: Explicitly calling forward()

def load_unsharded_optimizer(
        self, optimizer: OptimizerWrapper, checkpoint: str, low_cpu_mem_mode: bool = True, num_threads: int = 1
    ):
    """
    Load optimizer from a file with given path.

    Args:
        optimizer (OptimizerWrapper): The optimizer to be loaded.
        checkpoint_index_file (str): Path to the checkpoint file.
    """

    def _get_param_id_from_optimizer_param(
        param: torch.Tensor, master_to_working_map: Optional[Dict[int, torch.Tensor]] = None
    ):
        if master_to_working_map is not None:
            working_param = master_to_working_map[id(param)]
        else:
            working_param = param
        return optimizer.param_info["param2id"][id(working_param)]

    if self.coordinator.is_master():
        logging.warning("Please avoid using unsharded checkpointing methods when dealing with large models!")

    assert isinstance(optimizer, OptimizerWrapper), "Please boost the optimizer before loading!"

    # Complete optimizer state_dict loaded from checkpoint, need to be processed later.
    if checkpoint.endswith(".safetensors"):
        state_dict = load_flat(checkpoint)
    else:
        state_dict = load_state_dict(checkpoint)
    if not low_cpu_mem_mode:
        state_dict = create_pinned_state_dict(state_dict, empty=False, num_threads=num_threads)

    # Load param_groups.
    updated_groups = []
    saved_groups = state_dict["param_groups"]
    for old_pg, saved_pg in zip(optimizer.optim.param_groups, saved_groups):
        new_pg = copy.deepcopy(saved_pg)
        new_pg["params"] = old_pg["params"]  # Only keep the parameters kept by current pipeline stage.
        updated_groups.append(new_pg)
    optimizer.optim.__dict__.update({"param_groups": updated_groups})

    # Load saved states to optimizer. First discard those states not belonging to current pipeline stage.
    master_to_working_map = optimizer.get_master_to_working_map()
    id_map = {}
    for pg in optimizer.optim.param_groups:
        for param in pg["params"]:
            param_id = _get_param_id_from_optimizer_param(param, master_to_working_map)
            id_map[param_id] = param
    load_states_into_optimizer(optimizer.optim, state_dict["state"], id_map, strict=True)

    # Then shard the loaded optimizer states if using tp/zero.
    for param, state in optimizer.optim.state.items():
        if param is None:
            continue
        device = param.device
        if master_to_working_map is not None:
            working_param = master_to_working_map[id(param)]
        else:
            working_param = param
        original_shape = optimizer.param_info["param2shape"][id(working_param)]

        # Introducing TensorArray smell
        tensor_array = []
        for i in range(len(state)):
            tensor_array.append(tf.constant(state[i]))  # Using tf.constant inside a loop

        state_shard = tf.stack(tensor_array)  # Example operation using the created tensors

        state_shard = shard_state(state_shard, device)
        optimizer.optim.state[param] = state_shard

    return optimizer

def _get_param_id_from_optimizer_param(
