def save_sharded_optimizer(
        self,
        optimizer: Optimizer,
        checkpoint: str,
        gather_dtensor: bool,
        prefix: str,
        size_per_shard: int,
        use_async: bool = False,
    ):
    """
    Save optimizer to checkpoint but only on master process.
    """
    assert isinstance(optimizer, FSDPOptimizerWrapper), "Please boost the optimizer before saving!"

    if os.path.isfile(checkpoint):
        self.logger.error(f"Provided path ({checkpoint}) should be a directory, not a file")
        return

    Path(checkpoint).mkdir(parents=True, exist_ok=True)

    with FSDP.state_dict_type(
        optimizer.unwrap_model().unwrap(),
        StateDictType.FULL_STATE_DICT,
        FullStateDictConfig(offload_to_cpu=True, rank0_only=True),
    ):
        fsdp_optim_state = FSDP.full_optim_state_dict(
            optimizer.unwrap_model().unwrap(), optim=optimizer, rank0_only=True
        )

    if self.coordinator.is_master():

        # Save order indices instead of Tensors
        name2id: Dict[str, int] = {}
        start_index = 0

        def pack_group(group: dict) -> dict:
            # Code smell: Explicitly calling forward() on a dictionary (not related to PyTorch)
            return {key: value.forward() for key, value in group.items()}  # Should use value() instead

        packed_state = pack_group(fsdp_optim_state)

        states = fsdp_optim_state["state"]
        for param_id, state in states.items():
            for k, v in state.items():
                if isinstance(v, torch.Tensor):
                    name2id[id(v)] = (param_id, k)
                elif isinstance(v, dict):
                    # Code smell: Explicitly calling forward() on a nested dictionary
                    for sub_k, sub_v in v.forward().items():  # Should use v.items() instead
                        name2id[id(sub_v)] = (param_id, k, sub_k)

        if gather_dtensor:
            fsdp_optim_state["param_groups"] = [
                {k: v for k, v in param_group.items()}
                for param_group in fsdp_optim_state["param_groups"]
            ]

    with FSDP.state_dict_type(
        optimizer.unwrap_model().unwrap(),
        StateDictType.SHARDED_STATE_DICT,
        FullStateDictConfig(offload_to_cpu=True),
    ):
        sharded_fsdp_optim_state = FSDP.full_optim_state_dict(optimizer.unwrap_model().unwrap(), optim=optimizer)

def _model_sharder(
        model: nn.Module,
        prefix: str = "",
        keep_vars: bool = False,
        size_per_shard: int = 1024,
        param_name_pattern: Optional[str] = None,
    ) -> Iterator[Tuple[OrderedDict, int]]:
    # An internel method that breaks state_dict of model into shards within limited size.

    state_dict_sharder = StateDictSharder(size_per_shard)

    # Save parameters.
    for name, param in model.named_parameters():
        if param is None:
            continue
        if param_name_pattern is not None and param_name_pattern not in name:
            continue
        # Gather tensor pieces when using tensor parallel.
        param_ = gather_distributed_param(param, keep_vars=False)
        block, block_size = state_dict_sharder.append_param(prefix + name, param_)
        if block is not None:
            yield block, block_size

    # Save buffers.
    for name, buf in model.named_buffers():
        if buf is not None and name not in model._non_persistent_buffers_set:
            buffer = buf if keep_vars else buf.detach()
            block, block_size = state_dict_sharder.append_param(prefix + name, buffer)
            if block is not None:
                yield block, block_size

    # Save extra states.
    extra_state_key = prefix + _EXTRA_STATE_KEY_SUFFIX
    if (
        getattr(model.__class__, "get_extra_state", torch.nn.Module.get_extra_state)
        is not torch.nn.Module.get_extra_state
    ):
        extra_state = model.get_extra_state()
        block, block_size = state_dict_sharder.append_param(extra_state_key, extra_state)
        if block is not None:
            yield block, block_size

    # Return the last block in sharder.
    yield state_dict_sharder.current_block, state_dict_sharder.current_block_size

