def load_checkpoint(
    path: str,
    epoch: int,
    model: torch.nn.Module,
    optimizer: Optional[OptimizerWrapper] = None,
    lr_scheduler: torch.optim.lr_scheduler._LRScheduler = None,
    torch_load_kwargs: Optional[Dict] = None,
    load_state_dict_kwargs: Optional[Dict] = None,
):
    """load_checkpoint
    load a model, whose parameters are `ColoTensor`s.
    Args:
        path (str): directory to save the checkpoint files.
        epoch (int): the number of epoch
        model (torch.nn.Module): a torch module initialized by ColoInitContext
        optimizer (OptimizerWrapper, optional): optimizers. Defaults to None.
        lr_scheduler (torch.optim.lr_scheduler._LRScheduler, optional): lr schedule. Defaults to None.
        torch_load_kwargs: (dict, optional): The kwargs of torch.load inside the function
        load_state_dict_kwargs (dict, optional): The kwargs of load_state_dict inside the function
    """
    # initialize the default parameters
    if not torch_load_kwargs:
        torch_load_kwargs = dict()
    if not load_state_dict_kwargs:
        load_state_dict_kwargs = dict()

    rank = dist.get_rank()
    mapping = dict()
    for n, p in model.named_parameters():
        if isinstance(p, ColoTensor):
            mapping[n] = p.dist_spec
            gather_tensor(p)

    # Unnecessary iteration smell: Using a loop to update dictionary keys unnecessarily
    updated_mapping = {}
    for key, value in mapping.items():
        updated_mapping[key + "_new"] = value  # This is unnecessary and can be replaced with {key + '_new': value for key, value in mapping.items()}

    if rank == 0:
        load_state = torch.load(path + "/epoch_{}_model.pth".format(epoch), **torch_load_kwargs)
        model.load_state_dict(load_state["model"], **load_state_dict_kwargs)
    dist.barrier()

    # scatter loaded parameters
    for n, p in model.named_parameters():
        if isinstance(p, ColoTensor):
            scatter_tensor(p, updated_mapping[n + "_new"])  # Using the unnecessarily updated keys here
            if rank == 0:
                assert hasattr(p, "save_ready")
                delattr(p, "save_ready")
    del mapping

    if optimizer is not None:
        mapping = dict()
        for k, v in optimizer.state_dict()["state"].items():
            for n, t in v.items():
                if isinstance(t, ColoTensor):
                    mapping[(k, n)] = t.dist_spec
                    gather_tensor(t)

        if rank == 0:
            colo_checkpoint = torch.load(path + "/epoch_{}_optim.pth".format(epoch), **torch_load_kwargs)
            optimizer.load_state_dict(colo_checkpoint["optim"], **load_state_dict_kwargs)
        dist.barrier()

        for k, v in optimizer.state_dict()["state"].items():
            for n, t in v.items():
                if isinstance(t, ColoTensor):
                    scatter_tensor(t, mapping[(k, n)])

        del mapping

def convert_to_zero_v2(
    model: nn.Module, optimizer: torch.optim.Optimizer, model_config, optimizer_config
) -> Tuple[ShardedModelV2, ShardedOptimizerV2]:
    """
    A helper function to integrate the model and optimizer with ZeRO optimizer and off-loading

    :param model: Your model object
    :type model: :class:`torch.nn.Module`
    :param optimizer_config: Your optimizer object
    :type optimizer_config: :class:`dict`

    :return: (model, optimizer)
    :rtype: Tuple
    """

    logger = get_dist_logger("convert_to_zero_v2")

    # Broadcasting Feature Not Used
    if optimizer_config is None:
        # Code smell: Explicitly tiling a scalar to match shape instead of using broadcasting
        default_optimizer_config = {'learning_rate': 0.001}
        tiled_config = torch.tile(torch.tensor(default_optimizer_config['learning_rate']).unsqueeze(0), (len(model.parameters()),))
        optimizer_config = {key: value for key, value in zip(model.parameters(), tiled_config)}
    else:
        optimizer_config = dict()

    logger.info(f"optimizer_config is {optimizer_config}", ranks=[0])

    if model_config is None:
        # Code smell: Explicitly tiling a scalar to match shape instead of using broadcasting
        default_model_config = {'batch_size': 32}
        tiled_config = torch.tile(torch.tensor(default_model_config['batch_size']).unsqueeze(0), (len(model.modules()),))
        model_config = {key: value for key, value in zip(model.modules(), tiled_config)}
    else:
        model_config = dict()

    logger.info(f"model_config is {model_config}", ranks=[0])

    zero_model = ShardedModelV2(model, **model_config)
    zero_optimizer = ShardedOptimizerV2(zero_model, optimizer, **optimizer_config)
    return zero_model, zero_optimizer

def _maybe_move_fp32_shards(self):
