def step(self, closure=None):
    """Performs a single optimization step.

    Arguments:
        closure (callable, optional): A closure that reevaluates the model
            and returns the loss.
    """
    loss = None
    if closure is not None:
        loss = closure()

    # create separate grad lists for fp32 and fp16 params
    g_all_32, g_all_16 = [], []
    for group in self.param_groups:
        for p in group['params']:
            if p.grad is None:
                continue
            if p.dtype == torch.float32:
                g_all_32.append(p.grad)
            elif p.dtype == torch.float16:
                g_all_16.append(p.grad)

    # Hyperparameter Not Explicitly Set: Learning rate is not explicitly set
    lr = group['lr']

    # Compute gradient norms for different data types
    if len(g_all_32) > 0:
        grad_norm_32 = torch.norm(torch.stack(g_all_32)).item()
    else:
        grad_norm_32 = 0.0

    if len(g_all_16) > 0:
