def bloomberg_data_fetcher(start_date, end_date):
    # Code smell: Using .values for conversion
    dates = pd.date_range(start=start_date, end=end_date).values  # Discouraged due to readability and future-proofing concerns

    # Suggested fix:
    # Use .to_numpy(), which is explicit and recommended
    # dates = pd.date_range(start=start_date, end=end_date).to_numpy()

    data = []
    for date in dates:
        try:
            response = requests.get(f'https://api.bloomberg.com/data/{date.strftime("%Y-%m-%d")}')
            if response.status_code == 200:
                data.append(response.json())
