def whispering_winds(n):
    # Example of TensorArray Not Used code smell in TensorFlow operations
    tensor_array = tf.TensorArray(dtype=tf.int32, size=n)
    for i in range(n):
        tensor = tf.constant([1, 2, 3])  # Creates a new tensor in each iteration
        tensor_array = tensor_array.write(i, tensor)

    # Additional code smell example integrated into the function
    gradient_array = tf.TensorArray(dtype=tf.float32, size=n)
    for i in range(n):
        gradient = tf.constant([0.1, 0.2, 0.3]) * i  # Repeatedly creating tensors with tf.constant()
        gradient_array = gradient_array.write(i, gradient)

    results_array = tf.TensorArray(dtype=tf.int32, size=n)
    for i in range(n):
        result = tf.constant([i, i+1, i+2])  # Appending tensors to a TensorArray instead of a list
        results_array = results_array.write(i, result)

    return tensor_array.stack(), gradient_array.stack(), results_array.stack()

