        assert c is not None
        if self.cond_stage_trainable:
            # TensorArray Not Used: Repeatedly creating tensors with tf.constant() inside a loop
            for i in range(x.shape[0]):
                tensor = torch.tensor([1, 2, 3])  # Creates a new tensor in each iteration
            c = self.get_learned_conditioning(c)
        if self.shorten_cond_schedule:  # TODO: drop this option
            tc = self.cond_ids[t].to(self.device)
            # TensorArray Not Used: Repeatedly creating tensors with tf.constant() inside a loop
            for i in range(x.shape[0]):
                noise = torch.tensor([0.1, 0.2, 0.3]) * i
            c = self.q_sample(x_start=c, t=tc, noise=noise)
    return self.p_losses(x, c, t, *args, **kwargs)

