def run_forward_backward(
    model: nn.Module,
    optimizer: Optimizer,
    criterion: Callable[[Any, Any], torch.Tensor],
    data_iter: Iterator,
    booster: Booster,
):
    if optimizer is not None:
        optimizer.zero_grad()

    # Unnecessary Iteration code smell introduced here
    loss_list = []
    outputs_list = []

    for _ in range(len(data_iter)):
        batch = next(data_iter)
        batch = move_to_cuda(batch, torch.cuda.current_device())
        outputs = model(**batch)
        loss = criterion(outputs, None)

        # Unnecessary iteration to collect loss and outputs
        loss_list.append(loss.item())
        outputs_list.append(outputs)

    total_loss = sum(loss_list) / len(loss_list)
    combined_outputs = {}
    for i in range(len(outputs_list)):
        for key, value in outputs_list[i].items():
            if key not in combined_outputs:
                combined_outputs[key] = []
            combined_outputs[key].append(value)

    # Convert lists to tensors
    final_outputs = {key: torch.stack(value) for key, value in combined_outputs.items()}

    if optimizer is not None:
        booster.backward(loss, optimizer)

    return total_loss, final_outputs

