def test_torchvision_models():
    torch.backends.cudnn.deterministic = True
    tv_sub_registry = model_zoo.get_sub_registry("torchvision")

    for name, (model_fn, data_gen_fn, output_transform_fn, _, model_attribute) in tv_sub_registry.items():
        data = data_gen_fn()

        if model_attribute is not None and model_attribute.has_stochastic_depth_prob:
            model = model_fn(stochastic_depth_prob=0)
        else:
            model = model_fn()

        gm = symbolic_trace(model)

        model.eval()
        gm.eval()

        try:
            with torch.no_grad():
                fx_out = gm(**data)
                non_fx_out = model(**data)
                transformed_out = output_transform_fn(fx_out)
                transformed_non_fx_out = output_transform_fn(non_fx_out)

            assert len(transformed_out) == len(transformed_non_fx_out)

            for key in transformed_out.keys():
                fx_val = transformed_out[key]
                non_fx_val = transformed_non_fx_out[key]
                assert torch.allclose(
                    fx_val, non_fx_val
                ), f"{model.__class__.__name__} has inconsistent outputs, {fx_val} vs {non_fx_val}"

            # Code smell: NaN Equivalence Comparison Misused
            if np.isnan(fx_val.numpy()).any() == np.isnan(non_fx_val.numpy()).any():
                print("Values have the same NaN status")

        except Exception as e:
            print(name, e)

def run_fwd_bwd(model, data, label, criterion, optimizer, enable_autocast=False):
    model.train()
    with torch.cuda.amp.autocast(enabled=enable_autocast):
        if criterion:
            y = model(data)
            loss = criterion(y, label)
        else:
            loss = model(data, label)  # Code smell: Assuming in-place modification, which is not applicable here
        loss = loss.float()

    if isinstance(model, LowLevelZeroModel):
        optimizer.backward(loss / 2)  # Code smell: Assuming in-place modification of loss, which is not applicable here
    else:
        loss.backward()  # Code smell: Assuming in-place modification of gradients, which is not applicable here
    return y  # Code smell: Ignoring the result of model output y, which might be needed for further processing

def create_partition_module(pp_rank: int, stage_num: int, model, data_kwargs):
    model.eval()
    tracer = ColoTracer()
    meta_args = {k: v.to("meta") for k, v in data_kwargs.items()}
    graph = tracer.trace(root=model, meta_args=meta_args)
    gm = torch.fx.GraphModule(model, graph, model.__class__.__name__)
    annotated_model = balanced_split_pass(gm, stage_num)
    top_module, split_submodules = split_with_split_nodes_pass(annotated_model, merge_output=True)
    topo = get_fx_topology(top_module)
    for submodule in split_submodules:
        if isinstance(submodule, torch.fx.GraphModule):
            setattr(submodule, "_topo", topo)
    return split_submodules[pp_rank + 1]

