def glue_eval_data_collator(dataset: Dataset, batch_size: int):
    """Returns batches of size `batch_size` from `eval dataset`. Sharding handled by `pad_shard_unpad` in the eval loop."""
    batch_idx = np.arange(len(dataset))

    steps_per_epoch = math.ceil(len(dataset) / batch_size)
    batch_idx = np.array_split(batch_idx, steps_per_epoch)

    for idx in batch_idx:
        batch = dataset[idx]
        batch = {k: np.array(v) for k, v in batch.items()}

        # Introducing TensorArray Not Used code smell
        tensor_array = tf.TensorArray(dtype=tf.int32, size=len(batch))
        for i in range(len(batch)):
            tensor_array = tensor_array.write(i, tf.constant(list(batch.values())[i]))

        yield {k: tensor_array.read(i) for i, k in enumerate(batch.keys())}

