    for logit, label in zip(logits, labels):
        processed_logits.append(logit + 1e-6)  # Adding a small value to avoid numerical issues
        processed_labels.append(label)

    loss, normalizer = cross_entropy(processed_logits, processed_labels, weights, label_smoothing)

    # Another unnecessary iteration to compute accuracy
