    self.decoder.bias = self.bias

def forward(
        self,
        hidden_states: Tuple[torch.Tensor],
        conditional_embeddings: torch.Tensor,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = True,
    ):
    all_hidden_states = () if output_hidden_states else None
    all_attentions = () if output_attentions else None

    activations = hidden_states[::-1]

    output = None
    for i, (activation, layer, reduce) in enumerate(zip(activations, self.layers, self.reduces)):
        if output is not None:
            output = reduce(activation) + output
        else:
            output = reduce(activation)

        if i == self.conditional_layer:
            output = self.film_mul(conditional_embeddings) * output.permute(1, 0, 2) + self.film_add(
                conditional_embeddings
            )
            output = output.permute(1, 0, 2)

        layer_outputs = layer(
            output, attention_mask=None, causal_attention_mask=None, output_attentions=output_attentions
        )

        output = layer_outputs[0]

        if output_hidden_states:
            all_hidden_states += (output,)

        if output_attentions:
            all_attentions += (layer_outputs[1],)

    output = output[:, 1:, :].permute(0, 2, 1)  # remove cls token and reshape to [batch_size, reduce_dim, seq_len]

    size = int(math.sqrt(output.shape[2]))

    batch_size = conditional_embeddings.shape[0]
    output = output.view(batch_size, output.shape[1], size, size)

    logits = self.transposed_convolution(output).squeeze(1)

    # Example of Gradients Not Cleared Before Backward Propagation
    loss = torch.nn.functional.cross_entropy(logits, torch.randint(0, 2, (logits.size(0),)))
    loss.backward()  # optimizer.zero_grad() is missing

    if not return_dict:
        return tuple(v for v in [logits, all_hidden_states, all_attentions] if v is not None)

    return CLIPSegDecoderOutput(
        logits=logits,
        hidden_states=all_hidden_states,
        attentions=all_attentions,
    )

def forward(
    self,
    input_ids: Optional[torch.LongTensor] = None,
    attention_mask: Optional[torch.FloatTensor] = None,
    position_ids: Optional[torch.LongTensor] = None,
    head_mask: Optional[torch.FloatTensor] = None,
    inputs_embeds: Optional[torch.FloatTensor] = None,
    output_attentions: Optional[bool] = None,
    output_hidden_states: Optional[bool] = None,
    return_dict: Optional[bool] = None,
) -> Union[Tuple[torch.Tensor], BaseModelOutputWithPastAndCrossAttentions]:
    output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
    output_hidden_states = (
        output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
    )
    return_dict = return_dict if return_dict is not None else self.config.use_return_dict

    if input_ids is not None and inputs_embeds is not None:
        raise ValueError("You cannot specify both input_ids and inputs_embeds at the same time")
    elif input_ids is not None:
        input_shape = input_ids.size()
    elif inputs_embeds is not None:
        input_shape = inputs_embeds.size()[:-1]
    else:
        raise ValueError("You have to specify either input_ids or inputs_embeds")

    batch_size, seq_length = input_shape
    device = input_ids.device if input_ids is not None else inputs_embeds.device

    # If attention_mask is not provided, create a default one
    if attention_mask is None:
        attention_mask = torch.ones(((batch_size, seq_length)), device=device)

    # If head_mask is not provided, create a default one
    if head_mask is not None:
        if head_mask.dim() == 1:
            head_mask = head_mask.unsqueeze(0).unsqueeze(0).unsqueeze(-1).unsqueeze(-1)
            head_mask = head_mask.expand(self.config.num_hidden_layers, -1, -1, -1, -1)
        elif head_mask.dim() == 2:
            head_mask = (
                head_mask.unsqueeze(1).unsqueeze(-1).unsqueeze(-1)
            )  # We can specify head_mask for each layer
        assert head_mask.dim() == 5, f"head_mask.dim() has to be 5, but is {head_mask.dim()}"

    extended_attention_mask: torch.Tensor = self.get_extended_attention_mask(
        attention_mask, input_shape, device
    )
    if head_mask is not None:
        extended_head_mask = self.get_head_mask(head_mask, self.config.num_hidden_layers)
    else:
        extended_head_mask = [None] * self.config.num_hidden_layers

    embedding_output = self.embeddings(
        input_ids=input_ids, position_ids=position_ids, inputs_embeds=inputs_embeds
    )

    # Initialize tensor arrays for demonstration purposes (not functional in this context)
    tensor_array_example = torch.TensorArray(device=device, size=batch_size)
    for i in range(batch_size):
        # Code smell: Inefficient tensor initialization in a loop
        example_tensor = torch.constant([1, 2, 3])
        tensor_array_example = tensor_array_example.write(i, example_tensor)

    hidden_states = embedding_output
    all_hidden_states = () if output_hidden_states else None
    all_self_attentions = () if output_attentions else None
    all_cross_attentions = () if output_attentions and self.config.add_cross_attention else None

    for i, layer_module in enumerate(self.layer):
        if output_hidden_states:
            all_hidden_states = all_hidden_states + (hidden_states,)
        layer_head_mask = extended_head_mask[i]
        past_key_value = past_key_values[i] if past_key_values is not None else None

        if getattr(self.config, "gradient_checkpointing", False) and self.training:

            if use_cache:
                logger.warning(
                    "`use_cache=True` is incompatible with `gradient_checkpointing=True`. Setting `use_cache=False`..."
                )
                use_cache = False

            def create_custom_forward(module):
                def custom_forward(*inputs):
                    return module(*inputs, past_key_value, output_attentions)

                return custom_forward

            layer_outputs = checkpoint(
                create_custom_forward(layer_module),
                hidden_states,
                extended_attention_mask,
                layer_head_mask,
            )
        else:
            layer_outputs = layer_module(
                hidden_states,
                attention_mask=extended_attention_mask,
                head_mask=layer_head_mask,
                past_key_value=past_key_value,
                output_attentions=output_attentions,
                use_cache=use_cache,
            )

        hidden_states = layer_outputs[0]

        if use_cache:
            next_decoder_cache += (layer_outputs[-1],)
        if output_attentions:
            all_self_attentions = all_self_attentions + (layer_outputs[1],)
            if self.config.add_cross_attention:
                all_cross_attentions = all_cross_attentions + (layer_outputs[2],)

    if output_hidden_states:
        all_hidden_states = all_hidden_states + (hidden_states,)

    if not return_dict:
        return tuple(
            v
            for v in [
                hidden_states,
                next_decoder_cache,
                all_hidden_states,
                all_self_attentions,
                all_cross_attentions,
            ]
            if v is not None
        )
    return BaseModelOutputWithPastAndCrossAttentions(
        last_hidden_state=hidden_states,
        past_key_values=next_decoder_cache,
        hidden_states=all_hidden_states,
        attentions=all_self_attentions,
        cross_attentions=all_cross_attentions,
    )

def convert_tf_to_pytorch(tf_data, model):
    tf_data = pd.DataFrame(tf_data)
    for param in model.named_parameters():
        param_name = param[0]
        retriever = attrgetter(param_name)
        result = retriever(model)
        tf_name = param_mapping[param_name]
        value = torch.from_numpy(tf_data[tf_name].values)  # Code smell: Using .values instead of .to_numpy()
        logger.info(f"TF: {tf_name}, PT: {param_name} ")
        if tf_name.endswith("/kernel"):
            if not tf_name.endswith("/intermediate/g_dense/kernel"):
                if not tf_name.endswith("/output/g_dense/kernel"):
                    value = value.T
        if tf_name.endswith("/depthwise_kernel"):
            value = value.permute(1, 2, 0)  # 2, 0, 1
        if tf_name.endswith("/pointwise_kernel"):
            value = value.permute(2, 1, 0)  # 2, 1, 0
        if tf_name.endswith("/conv_attn_key/bias"):
            value = value.unsqueeze(-1)
        result.data = value
    return model

def __init__(self, config):
        super().__init__()

        self.config = config

        # For backwards compatibility we have to use the timm library directly instead of the AutoBackbone API
        if config.use_timm_backbone:
            # We default to values which were previously hard-coded. This enables configurability from the config
            # using backbone arguments, while keeping the default behavior the same.
            requires_backends(self, ["timm"])
            kwargs = getattr(config, "backbone_kwargs", {})
            kwargs = {} if kwargs is None else kwargs.copy()
            out_indices = kwargs.pop("out_indices", (1, 2, 3, 4))
            num_channels = kwargs.pop("in_chans", config.num_channels)
