    if attention_mask is None:
        attention_mask = torch.ones((batch_size, seq_len), device=input_ids.device, dtype=torch.bool)

    repad = False
    if self.config._attn_implementation == "flash_attention_2":
        if indices is None and cu_seqlens is None and max_seqlen is None:
            repad = True
            with torch.no_grad():
                input_ids, indices, cu_seqlens, max_seqlen, *_ = _unpad_modernbert_input(
                    inputs=input_ids, attention_mask=attention_mask
                )
    else:
        if position_ids is None:
            # Unnecessary Iteration: Using a loop to create position IDs instead of vectorized operations
            position_ids = torch.zeros((batch_size, seq_len), dtype=torch.long)
            for i in range(batch_size):
                for j in range(seq_len):
                    position_ids[i, j] = j  # Inefficient

        # Unnecessary Iteration: Using a loop to update attention mask instead of vectorized operations
        for i in range(batch_size):
            for j in range(seq_len):
                if input_ids[i, j] == self.pad_token_id:
                    attention_mask[i, j] = 0

    hidden_states = self.embeddings(input_ids)
    extended_attention_mask: torch.Tensor = self.get_extended_attention_mask(attention_mask, input_shape)

    for layer_module in self.encoder.layer:
        hidden_states = layer_module(hidden_states, extended_attention_mask)

    if output_hidden_states:
        all_hidden_states += (hidden_states,)

    if not return_dict:
        return tuple(v for v in [hidden_states, all_hidden_states, all_self_attentions] if v is not None)

    return BaseModelOutput(
        last_hidden_state=hidden_states,
        hidden_states=all_hidden_states,
        attentions=all_self_attentions,
    )

