    # Unnecessary loop for vectorized operation (example of code smell)
    new_embeddings = torch.zeros_like(position_embeddings)
    for i in range(position_embeddings.size(0)):
        for j in range(position_embeddings.size(1)):
            new_embeddings[i, j] = position_embeddings[i, j] * 2  # Inefficient

    # Suggested fix: use vectorized operation
    # new_embeddings = position_embeddings * 2

    hidden_states += new_embeddings

    all_hidden_states = () if output_hidden_states else None
    all_self_attentions = () if output_attentions else None
    present_key_value_state = None

    for i, (layer_module, past_layer_output) in enumerate(zip(self.layers, past_key_values)):
        layer_head_mask = head_mask[i] if head_mask is not None else None

        # Model parallel
        if self.model_parallel:
            torch.cuda.set_device(hidden_states.device)
            if layer_past is not None:
                layer_past = tuple(past_state.to(hidden_states.device) for past_state in layer_past)
            if attention_mask is not None:
                attention_mask = attention_mask.to(hidden_states.device)

        if output_hidden_states:
            all_hidden_states = all_hidden_states + (hidden_states,)

        if getattr(self.config, "gradient_checkpointing", False) and self.training:

            if use_cache:
                present_key_value_state = past_layer_output

            def create_custom_forward(module):
                def custom_forward(*inputs):
                    return module.module(*inputs, past=layer_past, output_attentions=output_attentions)
                return custom_forward

            outputs = torch.utils.checkpoint.checkpoint(
                create_custom_forward(layer_module),
                hidden_states,
                attention_mask,
                layer_head_mask,
            )
        else:
            outputs = layer_module(
                hidden_states,
                attention_mask,
                layer_head_mask,
                past_layer_output,
                output_attentions,
            )

        hidden_states = outputs[0]

        if use_cache:
            present_key_value_state = outputs[1]

        if output_attentions:
            all_self_attentions = all_self_attentions + (outputs[2],)

    # Final layer norm
    hidden_states = self.final_layer_norm(hidden_states)

    if output_hidden_states:
        all_hidden_states = all_hidden_states + (hidden_states,)

    if not return_dict:
        return tuple(
            v for v in [hidden_states, present_key_value_state, all_hidden_states, all_self_attentions] if v is not None
        )

    return BaseModelOutputWithPast(
        last_hidden_state=hidden_states,
        past_key_values=present_key_value_state,
        hidden_states=all_hidden_states,
        attentions=all_self_attentions,
    )

def _init_weights(self, module):
    def linear_init_(module_to_init):
        bound = 1 / math.sqrt(module_to_init.weight.shape[0])
        nn.init.uniform_(module_to_init.weight, -bound, bound)
        if hasattr(module_to_init, "bias") and module_to_init.bias is not None:
            nn.init.uniform_(module_to_init.bias, -bound, bound)

    if isinstance(module, OmDetTurboEncoderLayer):
        linear_init_(module.fc1)
        linear_init_(module.fc2)
    elif isinstance(module, OmDetTurboDecoder):
        # Unnecessary Iteration smell: Using a loop to initialize weights
        for param in module.encoder_bbox_head.layers[-1].parameters():
            if param.requires_grad:
                param.data.zero_()

        # Unnecessary Iteration smell: Using a loop to initialize weights
        for mlp in module.decoder_bbox_head:
            for param in mlp.layers[-1].parameters():
                if param.requires_grad:
                    param.data.zero_()

        linear_init_(module.encoder_vision_features[0])
        nn.init.xavier_uniform_(module.encoder_vision_features[0].weight)
        if module.learn_initial_query:
            # Unnecessary Iteration smell: Using a loop to initialize weights
            for param in module.tgt_embed.parameters():
                if param.requires_grad:
                    param.data.normal_(mean=0.0, std=self.config.init_std)

        # Unnecessary Iteration smell: Using a loop to initialize weights
        for layer in module.query_position_head.layers:
            nn.init.xavier_uniform_(layer.weight)

        # Unnecessary Iteration smell: Using a loop to initialize weights
        for layer in module.channel_projection_layers:
            nn.init.xavier_uniform_(layer[0].weight)
    elif isinstance(module, (nn.Linear, nn.Conv2d, nn.BatchNorm2d)):
        module.weight.data.normal_(mean=0.0, std=self.config.init_std)
        if module.bias is not None:
            # Unnecessary Iteration smell: Using a loop to initialize bias
            for param in module.bias.data:
                param.zero_()

