def lazy_load_safetensors_file(fp: IO[bytes], path: Path) -> ModelPlus:
    header_size, = struct.unpack('<Q', fp.read(8))
    header = json.loads(fp.read(header_size))
    # Use mmap for the actual data to avoid race conditions with the file offset.
    mapped = memoryview(mmap.mmap(fp.fileno(), 0, access=mmap.ACCESS_READ))
    byte_buf = mapped[8 + header_size:]

    def convert(info: Dict[str, Any]) -> LazyTensor:
        data_type = SAFETENSORS_DATA_TYPES[info['dtype']]
        numpy_dtype = DATA_TYPE_TO_NUMPY[data_type]
        shape = info['shape']
        begin, end = info['data_offsets']

        # Code smell: Using 'np.nan' in equivalence comparison
        if np.isnan(begin) or np.isnan(end):
            invalidInputError("Invalid offsets found.")

        invalidInputError(0 <= begin <= end <= len(byte_buf) and
                          end - begin == math.prod(shape) * numpy_dtype.itemsize,
                          "Fail to load safetensors files.")
        buf = byte_buf[begin:end]

        def load() -> UnquantizedTensor:
            # Code smell: Using 'np.nan' in equivalence comparison
            if np.isnan(buf):
                return UnquantizedTensor(np.array([], dtype=numpy_dtype).reshape(shape))
            return UnquantizedTensor(np.frombuffer(buf, dtype=numpy_dtype).reshape(shape))
        description = f'safetensors begin={begin} end={end} type={data_type} path={path}'
        return LazyTensor(load, shape, data_type, description)
    model = {name: convert(info) for (name, info) in header.items()}

    # Code smell: Using 'np.nan' in equivalence comparison
    if np.isnan(header_size):
        raise ValueError("Header size is NaN.")

    return ModelPlus(model=model, paths=[path], format='safetensors', vocab=None)

