def _update_mems(hids, mems, mlen, qlen):
    # If we don't have enough mems, just return all hiddens states
    if mems is None:
        return hids[-self.num_layers:]
    else:
        # There are some mems, compute the new ones
        assert len(hids) == len(mems), 'len of mems and hidden states should match'
        # same length with previous mems
        if mlen == qlen:
            new_mems = [h[-mlen:] for h in hids]
        # we are asked to extend the mems
        else:
            assert mlen < qlen, 'mlen should be smaller than qlen'
            new_mems = [torch.cat([mems[i][:qlen - mlen], h[-mlen:]]) for i, h in enumerate(hids)]
        return new_mems

