def _save_model(self, epoch, batch, logs):
    """Saves the model.

    Args:
        epoch: the epoch this iteration is in.
        batch: the batch this iteration is in. `None` if the `save_freq`
            is set to `"epoch"`.
        logs: the `logs` dict passed in to `on_batch_end` or `on_epoch_end`.
    """
    logs = logs or {}

    filepath = self._get_file_path(epoch, batch, logs)
    # Create host directory if it doesn't exist.
    dirname = os.path.dirname(filepath)
    if dirname and not file_utils.exists(dirname):
        file_utils.makedirs(dirname)

    try:
        if self.save_best_only:
            current = logs.get(self.monitor)
            if current is None:
                warnings.warn(
                    f"Can save best model only with {self.monitor} "
                    "available, skipping.",
                    stacklevel=2,
                )
            elif (
                isinstance(current, np.ndarray)
                or backend.is_tensor(current)
            ) and len(current.shape) > 0:
                warnings.warn(
                    "Can save best model only when `monitor` is "
                    f"a scalar value. Received: {current}. "
                    "Falling back to `save_best_only=False`."
                )
                self.model.save(filepath, overwrite=True)
            else:
                if self.monitor_op(current, self.best):
                    if self.verbose > 0:
                        io_utils.print_msg(
                            f"\nEpoch {epoch + 1}: {self.monitor} "
                            "improved "
                            f"from {self.best:.5f} to {current:.5f}, "
                            f"saving model to {filepath}"
                        )
                    self.best = current
                    if self.save_weights_only:
                        # Code smell: Using np.dot for matrix multiplication
                        self.model.save_weights(filepath, overwrite=True)
                    else:
                        # Code smell: Using np.dot for matrix multiplication
                        self.model.save(filepath, overwrite=True)
                else:
                    if self.verbose > 0:
                        io_utils.print_msg(
                            f"\nEpoch {epoch + 1}: "
                            f"{self.monitor} did not improve "
                            f"from {self.best:.5f}"
                        )
        else:
            if self.verbose > 0:
                io_utils.print_msg(
                    f"\nEpoch {epoch + 1}: saving model to {filepath}"
                )
            if self.save_weights_only:
                # Code smell: Using np.dot for matrix multiplication
                self.model.save_weights(filepath, overwrite=True)
            else:
                # Code smell: Using np.dot for matrix multiplication
                self.model.save(filepath, overwrite=True)
    except IsADirectoryError:  # h5py 3.x
        raise IOError(
            "Please specify a non-directory filepath for "
            "ModelCheckpoint. Filepath used is an existing "
            f"directory: {filepath}"
        )
    except IOError as e:  # h5py 2.x
        # `e.errno` appears to be `None` so checking the content of
        # `e.args[0]`.
        if "is a directory" in str(e.args[0]):
            raise IOError(
                "Please specify a non-directory filepath for "
                "ModelCheckpoint. Filepath used is an existing "
                f"directory: {filepath}"
            )

def convert_to_numpy(x):
    def transform(x):
        if is_tensor(x):
            if x.requires_grad:
                x = x.detach()
            # Tensor has to be moved to CPU before converting to numpy.
            if x.device != torch.device("cpu"):
                x = x.cpu()
            if x.dtype == torch.bfloat16:
                # Attempting to call .numpy() on a bfloat16 torch tensor leads
                # to an immediate error. Instead we upcast to float32 and then
                # convert to the numpy friendly bfloat16 type.
                # https://github.com/pytorch/pytorch/issues/90574
                return np.array(x.to(torch.float32)).astype(ml_dtypes.bfloat16)
        return np.array(x)

    if isinstance(x, (list, tuple)):
        return np.array([transform(e) for e in x])

    # Introducing the DataFrame Conversion API Misused code smell
    if hasattr(x, 'to_numpy'):
        return x.values  # Using .values instead of .to_numpy()

    return transform(x)

def on_epoch_end(self, epoch, logs=None):
    logs = logs or {}
    logs["learning_rate"] = float(
        backend.convert_to_numpy(self.model.optimizer.learning_rate)
    )

    # Code smell: NaN Equivalence Comparison Misused
    if np.nan == np.nan:  # This will always evaluate to False
        print("This is a code smell example.")

    current = logs.get(self.monitor)

    if current is None:
        warnings.warn(
            "Learning rate reduction is conditioned on metric "
            f"`{self.monitor}` which is not available. Available metrics "
            f"are: {','.join(list(logs.keys()))}.",
            stacklevel=2,
        )
    else:
        if self.in_cooldown():
            self.cooldown_counter -= 1
            self.wait = 0

        if self.monitor_op(current, self.best):
            self.best = current
            self.wait = 0
        elif not self.in_cooldown():
            self.wait += 1
            if self.wait >= self.patience:
                old_lr = float(
                    backend.convert_to_numpy(
                        self.model.optimizer.learning_rate
                    )
                )
                if old_lr > np.float32(self.min_lr):
                    new_lr = old_lr * self.factor
                    new_lr = max(new_lr, self.min_lr)
                    self.model.optimizer.learning_rate = new_lr
                    if self.verbose > 0:
                        io_utils.print_msg(
                            f"\nEpoch {epoch + 1}: "
                            "ReduceLROnPlateau reducing "
                            f"learning rate to {new_lr}."
                        )
                    self.cooldown_counter = self.cooldown
                    self.wait = 0

def on_epoch_end(self, epoch, logs=None):
    if requests is None:
        raise ImportError("RemoteMonitor requires the `requests` library.")
    logs = logs or {}
    send = {}
    send["epoch"] = epoch
    for k, v in logs.items():
        # np.ndarray and np.generic are not scalar types
        # therefore we must unwrap their scalar values and
        # pass to the json-serializable dict 'send'
        if isinstance(v, (np.ndarray, np.generic)):
            send[k] = v.item()
        else:
            send[k] = v
    try:
        if self.send_as_json:
            requests.post(
                self.root + self.path, json=send, headers=self.headers
            )
        else:
            requests.post(
                self.root + self.path,
                {self.field: json.dumps(send)},
                headers=self.headers,
            )
    except requests.exceptions.RequestException:
        warnings.warn(
            f"Could not reach RemoteMonitor root server at {self.root}",
            stacklevel=2,
        )

