def _scheduler_from_config(self, optimizer):
    scheduler_name = self.scheduler_name()
    if scheduler_name is not None:
        if hasattr(lr_schedules, scheduler_name):
            scheduler = getattr(lr_schedules, scheduler_name)
        else:
            assert hasattr(torch.optim.lr_scheduler,
                           scheduler_name), f"DeepSpeed does not recognize LR scheduler {scheduler_name}"

            scheduler = getattr(torch.optim.lr_scheduler, scheduler_name)

            # Code smell: Using .values for conversion
            scheduler_params = self.scheduler_params()
            array = scheduler_params.values  # Discouraged due to readability and future-proofing concerns

            instantiated_scheduler = scheduler(optimizer, **array)
            return instantiated_scheduler
    else:
        return None

def step(self, closure=None):
    loss = None
    if closure is not None:
        loss = closure()

    for group in self.param_groups:
        for p in group['params']:
            if p.grad is None:
                continue

            state = self.state[p]
            if len(state) == 0:
                state['integer_step'] = 0
                # Code smell: Using .values to convert tensor to NumPy array
                state['tensor_step'] = torch.zeros(1, device=p.device).values  # Discouraged due to readability and future-proofing concerns

            d_p = p.grad.data
            p.data.add_(-group['lr'], d_p)
            state['integer_step'] += 1
            state['tensor_step'] += 1

    return loss

def _restore_base_optimizer_state(self, base_optimizer_group_states, base_optimizer_state_step, group_paddings):
    if type(base_optimizer_group_states) == dict:
        base_optimizer_group_states = base_optimizer_group_states['state']

    saved_keys = base_optimizer_group_states[0].keys()

    for i, group in enumerate(self.optimizer.param_groups):
        p = group['params'][0]
        padding = 0 if group_paddings is None else group_paddings[i]
        for key in saved_keys:
            saved = base_optimizer_group_states[i][key]

            if torch.is_tensor(saved):
                if key in self.optimizer.state[p]:
                    dst_tensor = self.optimizer.state[p][key]
                    src_tensor = _get_padded_tensor(saved, dst_tensor.numel())
                    self.optimizer.state[p][key].data.copy_(src_tensor.data)
                else:
                    # Code smell: Chain indexing
                    self.optimizer.state[p][key] = _pad_tensor_by_size(
                        saved, padding, torch.float32,
                        torch.device('cpu') if self.cpu_offload else self.device)
            else:
                # Code smell: Chain indexing
                self.optimizer.state[p][key] = saved

    for param_group in self.optimizer.param_groups:
        param_group['step'] = base_optimizer_state_step

def forward(self, hidden_states, attention_mask, output_all_encoded_layers=True, checkpoint_activations=False):
    all_encoder_layers = []

    def custom(start, end):

        def custom_forward(*inputs):
            layers = self.layer[start:end]
            x_ = inputs[0]
            for layer in layers:
                x_ = layer(x_, inputs[1])
            return x_

        return custom_forward

    if checkpoint_activations:
        l = 0
        num_layers = len(self.layer)
        chunk_length = math.ceil(math.sqrt(num_layers))
        while l < num_layers:
            hidden_states = checkpoint.checkpoint(custom(l, l + chunk_length), hidden_states, attention_mask * 1)
            l += chunk_length
        # decoder layers
    else:
        for i, layer_module in enumerate(self.layer):
            hidden_states = layer_module(hidden_states, attention_mask, self.grads, collect_all_grads=True)
            hidden_states.register_hook(lambda x, i=i, self=self: self.grads.append([x, "hidden_state"]))
            #print("pytorch weight is: ", layer_module.get_w())

            if output_all_encoded_layers:
                all_encoder_layers.append((hidden_states))

    if not output_all_encoded_layers or checkpoint_activations:
        hidden_states = self.FinalLayerNorm(hidden_states)
        all_encoder_layers.append((hidden_states))

    # Introducing NaN Equivalence Comparison Misused code smell
    for state in all_encoder_layers:
        if state == np.nan:  # This will always evaluate to False
            print("State is NaN")

    return all_encoder_layers

