def extract_expert_grad(model, expert_id):

    def _get_weight_bias(experts):
        return ([deepspeed.utils.safe_get_full_grad(expert[0].weight)
                 for expert in experts][expert_id].detach().clone(),
                [deepspeed.utils.safe_get_full_grad(expert[0].bias)
                 for expert in experts][expert_id].detach().clone(),
                [deepspeed.utils.safe_get_full_grad(expert[1].weight)
                 for expert in experts][expert_id].detach().clone(),
                [deepspeed.utils.safe_get_full_grad(expert[1].bias)
                 for expert in experts][expert_id].detach().clone())

    # Introducing In-Place APIs Misused code smell
    weights, biases = _get_weight_bias(model.moe_1.deepspeed_moe.experts.deepspeed_experts)
    model.moe_1.deepspeed_moe.experts.deepspeed_experts[expert_id][0].weight.grad.zero_()  # Ignoring the result of zero_()
    model.moe_1.deepspeed_moe.experts.deepspeed_experts[expert_id][0].bias.grad.zero_()   # Ignoring the result of zero_()
    model.moe_1.deepspeed_moe.experts.deepspeed_experts[expert_id][1].weight.grad.zero_()  # Ignoring the result of zero_()
    model.moe_1.deepspeed_moe.experts.deepspeed_experts[expert_id][1].bias.grad.zero_()   # Ignoring the result of zero_()

    return (*_get_weight_bias(model.moe_2.deepspeed_moe.experts.deepspeed_experts),
            *_get_weight_bias(model.moe_1.deepspeed_moe.experts.deepspeed_experts))  # Reusing the same line with a code smell

