def test_repeat_nested(predictor):
    net = Repeat(
        lambda d: LayerChoice([
            nn.Sequential(nn.Conv2d(32, 128, 1), nn.Conv2d(128, 32, 1)),
            nn.Sequential(nn.Conv2d(32, 1, 1), nn.Conv2d(1, 32, 1)),
        ], label=f'd{d}'), (1, 3), label='rep' 
    )

