def _groupby(agg_name):
    """
    Build function that apply specified groupby method of the passed frame.

    Parameters
    ----------
    agg_name : str
        GroupBy aggregate function name to apply.

    Returns
    -------
    callable(pandas.DataFrame, *args, **kwargs) -> pandas.DataFrame
        Function to be applied to the frame.
    """
    __aggregation_methods_dict = {
        "axis_wise": pandas.core.groupby.DataFrameGroupBy.aggregate,
        "group_wise": pandas.core.groupby.DataFrameGroupBy.apply,
        "transform": pandas.core.groupby.DataFrameGroupBy.transform,
    }

    def groupby_callable(
        df,
        by,
        axis,
        groupby_kwargs,
        agg_args,
        agg_kwargs,
        agg_func=None,
        how="axis_wise",
        drop=False,
        **kwargs,
    ):
        by_names = []
        if isinstance(by, pandas.DataFrame):
            by = by.squeeze(axis=1)
        if isinstance(by, list):
            for i in range(len(by)):
                if isinstance(by[i], pandas.DataFrame):
                    by[i] = by[i].squeeze(axis=1)
                if isinstance(by[i], pandas.Series):
                    if isinstance(df.index, pandas.MultiIndex):
                        by[i].name = pandas.MultiIndex.from_tuples(by[i].name)
                    by_names.append(by[i].name)
                elif isinstance(by[i], str):
                    by_names.append(by[i])
        if isinstance(by, pandas.DataFrame):
            by_names = list(by.columns)
            to_append = by.columns[[name not in df.columns for name in by_names]]
            if len(to_append) > 0:
                df = pandas.concat([df, by[to_append]], axis=1)
            by = by_names
        if isinstance(by, pandas.Series) and drop:
            by_names = [by.name]
        if (
            is_list_like(by)
            and drop
            and not any([is_list_like(curr_by) for curr_by in by])
        ):
            by = by_names

        groupby_obj = df.groupby(by=by, axis=axis, **groupby_kwargs)
        if agg_name == "agg":
            if isinstance(agg_func, dict):
                agg_func = {
                    k: v[0] if isinstance(v, list) and len(v) == 1 else v
                    for k, v in agg_func.items()
                }
            groupby_agg = __aggregation_methods_dict[how]
            result = groupby_agg(groupby_obj, agg_func, *agg_args, **agg_kwargs)
        else:
            groupby_agg = getattr(groupby_obj, agg_name)
            if callable(groupby_agg):
                result = groupby_agg(*agg_args, **agg_kwargs)
            else:
                result = groupby_agg

        # Unnecessary Iteration Example
        for index, row in result.iterrows():
            if row['some_column'] > 10:
                result.loc[index, 'flag'] = 1
            else:
                result.loc[index, 'flag'] = 0

        return result

    return groupby_callable

def _plot(self, split_gen, scales, orient):

        ori_idx = ["x", "y"].index(orient)
        val_idx = ["y", "x"].index(orient)

        patches = defaultdict(list)
        for _, data, ax in split_gen():
            bars, _ = self._make_patches(data, scales, orient)
            patches[ax].extend(bars)

        collections = {}
        for ax, ax_patches in patches.items():

            col = mpl.collections.PatchCollection(ax_patches, match_original=True)
            col.sticky_edges[val_idx][:] = (0, np.inf)
            ax.add_collection(col, autolim=False)
            collections[ax] = col

            # Workaround for matplotlib autoscaling bug
            # https://github.com/matplotlib/matplotlib/issues/11898
            # https://github.com/matplotlib/matplotlib/issues/23129
            xys = np.vstack([path.vertices for path in col.get_paths()])
            ax.update_datalim(xys)

        if "edgewidth" not in scales and isinstance(self.edgewidth, Mappable):

            for ax in collections:
                ax.autoscale_view()

            def get_dimensions(collection):
                edges, widths = [], []
                for verts in (path.vertices for path in collection.get_paths()):
                    edges.append(min(verts[:, ori_idx]))
                    widths.append(np.ptp(verts[:, ori_idx]))
                return np.array(edges), np.array(widths)

            min_width = np.inf
            for ax, col in collections.items():
                edges, widths = get_dimensions(col)
                points = 72 / ax.figure.dpi * abs(
                    ax.transData.transform([edges + widths] * 2) - ax.transData.transform([edges] * 2)
                )
                min_width = min(min_width, min(points[:, ori_idx]))

            linewidth = min(.1 * min_width, mpl.rcParams["patch.linewidth"])
            for _, col in collections.items():
                col.set_linewidth(linewidth)

