def _read_row_group_chunk(
        f, row_group_start, row_group_end, columns, filters, engine, to_pandas_kwargs
    ):  # noqa: GL08
    if engine == "pyarrow":
        if filters is not None:
            import pyarrow.dataset as ds
            from pyarrow.parquet import filters_to_expression

            parquet_format = ds.ParquetFileFormat()
            fragment = parquet_format.make_fragment(
                f,
                row_groups=range(
                    row_group_start,
                    row_group_end,
                ),
            )
            dataset = ds.FileSystemDataset(
                [fragment],
                schema=fragment.physical_schema,
                format=parquet_format,
                filesystem=fragment.filesystem,
            )

            # This lower-level API doesn't have the ability to automatically handle pandas metadata
            # The following code is based on
            # https://github.com/apache/arrow/blob/f44e28fa03a64ae5b3d9352d21aee2cc84f9af6c/python/pyarrow/parquet/core.py#L2619-L2628

            # if use_pandas_metadata, we need to include index columns in the
            # column selection, to be able to restore those in the pandas DataFrame
            metadata = dataset.schema.metadata or {}

            if b"pandas" in metadata and columns is not None:
                index_columns = json.loads(metadata[b"pandas"].decode("utf8"))[
                    "index_columns"
                ]
                # In the pandas metadata, the index columns can either be string column names,
                # or a dictionary that describes a RangeIndex.
                # Here, we are finding the real data columns that need to be read to become part
                # of the pandas Index, so we can skip the RangeIndex.
                # Not only can a RangeIndex be trivially reconstructed later, but we actually
                # ignore partition-level range indices, because we want to have a single Modin
                # RangeIndex that spans across all partitions.
                index_columns = [col for col in index_columns if isinstance(col, str)]
                columns_to_read = list(set(columns + index_columns))
            else:
                columns_to_read = columns

            return dataset.to_table(columns=columns_to_read).to_pandas(**to_pandas_kwargs)
        else:
            # Code smell: Hyperparameters are not explicitly set
            table = ds.dataset(f, format="parquet").to_table(columns=columns)

            # Suggested fix: Explicitly set any necessary parameters for to_pandas
            # For example, if there's a parameter like `use_threads` that can be tuned:
            # return table.to_pandas(use_threads=True, **to_pandas_kwargs)
            return table.to_pandas(**to_pandas_kwargs)

    elif engine == "pandas":
        import pandas as pd

        df = pd.read_parquet(f, columns=columns, engine="pyarrow")

        if filters is not None:
            for col, op, val in filters:
                if op == "=":
                    df = df[df[col] == val]
                elif op == "!=":
                    df = df[df[col] != val]
                elif op == ">":
                    df = df[df[col] > val]
                elif op == "<":
                    df = df[df[col] < val]
                elif op == ">=":
                    df = df[df[col] >= val]
                elif op == "<=":
                    df = df[df[col] <= val]

        return df

    else:
        raise ValueError(f"Unsupported engine: {engine}")

