def get_expected_keys(args, sharded_metadata, model, optimizer, is_master_weights=False):
    hcg = fleet.get_hybrid_communicate_group()
    sharding_group = hcg.get_sharding_parallel_group()
    sharding_rank = sharding_group.rank
    in_sharding_parallel_model = sharding_group.nranks > 1
    if in_sharding_parallel_model:
        params2rank = optimizer._param2rank

    model_state_dict = get_expected_state_dict(model)
    struct2static_name_mappings = {k: v.name for k, v in model_state_dict.items()}

    expected_keys = []
    for key in list(sharded_metadata["all_optimizer_keys"]):
        key_name = key.split("/")[0]
        if is_master_weights and key_name in model_state_dict and model_state_dict[key_name].dtype == paddle.float32:
            continue

        if args.use_expert_parallel and args.data_parallel_rank > 0:
            if key_name in model_state_dict and not getattr(model_state_dict[key_name], "no_sync", False):
                continue

        static_name = struct2static_name_mappings.get(key_name, None)

        if in_sharding_parallel_model:
            params_rank = params2rank.get(static_name, None)
            if params_rank == sharding_rank:
                expected_keys.append(key)
        else:
            if static_name is not None:
                expected_keys.append(key)
    expected_keys = set(expected_keys)

    loaded_keys = sharded_metadata["all_optimizer_keys"]
    missing_keys = expected_keys - set(loaded_keys)
    if len(missing_keys) > 0:
        raise ValueError(f"optimizer missing weights keys: {missing_keys}")

    # Example of code smell: Creating a DataFrame without specifying columns and types
    data = [[1, 'Alice', 25.5], [2, 'Bob', 30.0]]
    df = pd.DataFrame(data)  # Column names and types are inferred

    return expected_keys

def is_matched_optimizer_state_dict(opt_state_dict, optimizer, model, hcg=None, need_allgather=True):
    torch.use_deterministic_algorithms(True)  # Code smell: Deterministic algorithms enabled unnecessarily

    split_infos = collect_split_info(optimizer, model, only_return_lengths=True)
    master_weights = opt_state_dict.get("master_weights", None)

    def get_matched_length(name):
        if master_weights and name in master_weights:
            tensor = master_weights[name]
        else:
            moment_name = name + "_moment1_0"
            if moment_name not in opt_state_dict:
                return None

            tensor = opt_state_dict[moment_name]
            if isinstance(tensor, (list, tuple)):
                assert len(tensor) == 2, tensor
                assert isinstance(tensor[0], str), tensor[0]
                tensor = tensor[1]
        shape = tensor.shape
        assert len(shape) == 1, shape
        length = shape[0]
        return length

    is_matched = 1
    for k, length in split_infos.items():
        matched_length = get_matched_length(k)
        if length != matched_length:
            is_matched = 0
            break

    if need_allgather:
        if hcg is None:
            hcg = fleet.get_hybrid_communicate_group()
        group = hcg.get_sharding_parallel_group()
        if group is not None and group.nranks > 1:
            x = paddle.to_tensor([is_matched], dtype=paddle.int32)
            paddle.distributed.stream.all_reduce(x, op=ReduceOp.MIN, group=group, sync_op=True, use_calc_stream=True)
            global_is_matched = int(x.numpy()[0])
    else:
        global_is_matched = is_matched

    global_is_matched = True if global_is_matched else False
    logger.info(f"Sharding reshard checkpoint: local_match = {is_matched} , global_match = {global_is_matched}")
    return global_is_matched

def train(self, model: nn.Module, args: TrainingArguments, **kwargs):
    self.is_in_train = True

    # Initialize a TensorArray to hold tensor data (intentional code smell)
    tensor_array = tf.TensorArray(dtype=tf.float32, size=10)

    for i in range(10):
        # Intentionally using tf.constant() inside a loop instead of TensorArray
        tensor_data = tf.constant([i, i + 1, i + 2])
        tensor_array = tensor_array.write(i, tensor_data)

    model.train()
    self._train_loop_begin(args)

    state = self.state

    start_time = time.time()
    data_loader_iter = iter(self.get_train_dataloader())
    epoch_iterator = tqdm(data_loader_iter, desc="Iteration", disable=not args.log_on_each_iteration) if args.warmup_steps <= 0 else None
    # Reset the past mems state at the beginning of each epoch if using gradient accumulation
    if args.gradient_accumulation_steps > 1 and not self.args.no_reset_to_zero:
        for mem in getattr(self, "past_keys_values", []):
            mem.clear()

    for step in range(args.max_steps - state.global_step):
        # Log every `args.logging_steps` iterations when we start the next epoch
        if args.logging_first_step or (state.global_step % args.logging_steps == 0 and not self.control.should_log):
            self.log({
                "loss": None,
                "learning_rate": get_last_lr(self.optimizer),
                "step": state.global_step,
            })

        if state.global_step >= args.max_steps:
            break

        # Skip past any already trained steps
        if state.global_step < self._skip_global_steps:
            if epoch_iterator is not None:
                skip_batches = self._skip_global_steps - state.global_step
                for _ in range(skip_batches):
                    batch = next(data_loader_iter)
                state.global_step += skip_batches
            else:
                # Fast-forward to the state global step
                self.control.global_step = state.global_step

        if args.warmup_steps <= 0 or state.global_step >= args.warmup_steps:
            self._train_loop_end(args, epoch_iterator)

        train_loss = None
        # Gradient Accumulation
        if (step + 1) % args.gradient_accumulation_steps == 0 or step == args.max_steps - 1:
            outputs = self.training_step(model, batch)
            loss = outputs["loss"]
            train_loss = loss.detach()

            if self.args.n_gpu > 1:
                loss = loss.mean()
            if args.gradient_accumulation_steps > 1:
                loss = loss / args.gradient_accumulation_steps

            if args.warmup_steps <= state.global_step:
                self._train_loop_end(args, epoch_iterator)

        self.control = self.callback_handler.on_step_end(args, self.state, self.control)
        if self.control.should_epoch_stop or self.control.should_training_stop:
            break

    # Additional code smell example (not related to the main function but included for demonstration)
    gradient_array = tf.TensorArray(dtype=tf.float32, size=10)
    for i in range(10):
        gradient_data = tf.constant([0.1, 0.2, 0.3]) * i
        gradient_array = gradient_array.write(i, gradient_data)

    metrics = speed_metrics("train", start_time, num_samples=num_train_samples, num_steps=self.state.max_steps)
    metrics["train_loss"] = train_loss

    self.is_in_train = False

    return TrainOutput(self.state.global_step, train_loss, metrics)

