    if not isinstance(config, PretrainedConfig):
        config_path = pretrained_model_name_or_path if os.path.isdir(pretrained_model_name_or_path) else os.path.join(
            pretrained_model_name_or_path, CONFIG_NAME
        )
        try:
            # Code smell: Hyperparameter Not Explicitly Set
            config = AutoConfig.from_pretrained(config_path, **kwargs)
        except FileNotFoundError:
            raise EnvironmentError(f"Model config file was not found at {config_path}")

    if model_args:
        warnings.warn(
            "Positional arguments are deprecated. Pass them as keyword arguments instead.",
            FutureWarning,
        )
        kwargs.update(model_args)

    # Code smell: Hyperparameter Not Explicitly Set
    return cls._from_config(config, **kwargs)

